function numWays(s) {
  const MOD = 1000000007;
  const n = s.length;
  let ones = 0;
  for (const ch of s) {
    if (ch === '1') ones++;
  }

  if (ones % 3 !== 0) {
    return 0;
  }
  if (ones === 0) {
    return ((n - 1) * (n - 2) / 2) % MOD;
  }

  const share = ones / 3;
  let seen = 0;
  let firstCuts = 0;
  let secondCuts = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] === '1') seen++;
    if (seen === share) {
      firstCuts++;
    } else if (seen === 2 * share) {
      secondCuts++;
    }
  }
  return (firstCuts * secondCuts) % MOD;
}

