function numWays(s) {
  const count = piece => piece.split('').filter(ch => ch === '1').length;
  let ways = 0;
  for (let i = 1; i < s.length - 1; i++) {
    for (let j = i + 1; j < s.length; j++) {
      const a = count(s.slice(0, i)), b = count(s.slice(i, j)), c = count(s.slice(j));
      if (a === b && b === c) ways++;
    }
  }
  return ways % 1000000007;
}

