function generate(rand, size) {
  const n = size === 'small' ? 3 + Math.floor(rand() * 12) : 8000 + Math.floor(rand() * 2001);
  const mode = Math.floor(rand() * 4);
  const density = mode === 0 ? 0 : mode === 1 ? 0.5 : size === 'small' ? 0.3 : 0.002;
  const bits = Array.from({ length: n }, () => (rand() < density ? '1' : '0'));
  // Most inputs get a multiple of three ones so the answer is usually not zero.
  if (mode !== 3 || rand() < 0.5) {
    let ones = bits.filter(b => b === '1').length;
    while (ones % 3 !== 0) {
      const i = Math.floor(rand() * n);
      ones += bits[i] === '1' ? -1 : 1;
      bits[i] = bits[i] === '1' ? '0' : '1';
    }
  }
  return [bits.join('')];
}
